type Ticket = { kind: 'adult' | 'child' | 'senior'; base: number };
function price(ticket: Ticket) {
  switch (ticket.kind) {
    case 'adult': return ticket.base;
    case 'child': return ticket.base * 0.5;
    case 'senior': return ticket.base * 0.8;
    default: throw new Error('unknown kind');
  }
}

// This switch appears across cart, reports, and checkout modules.

// Version A
const paymentHandlers: Record<string, (p: any) => void> = {
  card: (p) => { /* uses p.cardNumber, shared externally */ },
  paypal: (p) => { /* uses p.email, shared externally */ }
};
function processPayment(p: any) { return paymentHandlers[p.type](p); }

// Version B
abstract class Payment { abstract process(): void }
class CardPayment extends Payment { constructor(private cardNumber: string) { super() } process() { /* uses cardNumber */ } }
class PaypalPayment extends Payment { constructor(private email: string) { super() } process() { /* uses email */ } }

// Version A centralizes handlers; Version B encapsulates behavior in subclasses.
